static bool is_in_intervals(unicode_codepoint_t cp, const unicode_interval_t* table,
                            size_t length) {
    size_t low = 0;
    size_t high = length;
    while (low < high) {
        size_t mid = low + ((high - low) / 2);
        if (cp > table[mid].last) {
            low = mid + 1;
        } else if (cp < table[mid].first) {
            high = mid;
        } else {
            return true;
        }
    }
    return false;
}

bool unicode_decode_utf8(const uint8_t* data, ssize_t length, unicode_codepoint_t* codepoint,
                         ssize_t* bytes_read) {
    if (codepoint == NULL || bytes_read == NULL) {
        return false;
    }
    if (data == NULL || length <= 0) {
        *codepoint = 0;
        *bytes_read = 0;
        return false;
    }

    const uint8_t c0 = data[0];
    if (c0 < 0x80) {
        *codepoint = c0;
        *bytes_read = 1;
        return true;
    }

    if ((c0 & 0xE0) == 0xC0) {
        if (length < 2) {
            goto invalid_sequence;
        }
        const uint8_t c1 = data[1];
        if ((c1 & 0xC0) != 0x80 || c0 <= 0xC1) {
            goto invalid_sequence;
        }
        *codepoint = ((c0 & 0x1F) << 6) | (c1 & 0x3F);
        *bytes_read = 2;
        return true;
    }

    if ((c0 & 0xF0) == 0xE0) {
        if (length < 3) {
            goto invalid_sequence;
        }
        const uint8_t c1 = data[1];
        const uint8_t c2 = data[2];
        if ((c1 & 0xC0) != 0x80 || (c2 & 0xC0) != 0x80) {
            goto invalid_sequence;
        }
        if (c0 == 0xE0 && c1 < 0xA0) {
            goto invalid_sequence;
        }
        if (c0 == 0xED && c1 >= 0xA0) {
            goto invalid_sequence;
        }
        *codepoint = ((c0 & 0x0F) << 12) | ((c1 & 0x3F) << 6) | (c2 & 0x3F);
        *bytes_read = 3;
        return true;
    }

    if ((c0 & 0xF8) == 0xF0) {
        if (length < 4) {
            goto invalid_sequence;
        }
        const uint8_t c1 = data[1];
        const uint8_t c2 = data[2];
        const uint8_t c3 = data[3];
        if ((c1 & 0xC0) != 0x80 || (c2 & 0xC0) != 0x80 || (c3 & 0xC0) != 0x80) {
            goto invalid_sequence;
        }
        if (c0 == 0xF0 && c1 < 0x90) {
            goto invalid_sequence;
        }
        if (c0 == 0xF4 && c1 > 0x8F) {
            goto invalid_sequence;
        }
        *codepoint = ((c0 & 0x07) << 18) | ((c1 & 0x3F) << 12) | ((c2 & 0x3F) << 6) | (c3 & 0x3F);
        *bytes_read = 4;
        return true;
    }

invalid_sequence:
    *codepoint = c0;
    *bytes_read = 1;
    return false;
}

int unicode_encode_utf8(unicode_codepoint_t codepoint, uint8_t out[4]) {
    if (!unicode_is_valid_codepoint(codepoint) || out == NULL) {
        return 0;
    }

    if (codepoint < 0x80) {
        out[0] = (uint8_t)codepoint;
        return 1;
    }
    if (codepoint < 0x800) {
        out[0] = (uint8_t)(0xC0 | (codepoint >> 6));
        out[1] = (uint8_t)(0x80 | (codepoint & 0x3F));
        return 2;
    }
    if (codepoint < 0x10000) {
        out[0] = (uint8_t)(0xE0 | (codepoint >> 12));
        out[1] = (uint8_t)(0x80 | ((codepoint >> 6) & 0x3F));
        out[2] = (uint8_t)(0x80 | (codepoint & 0x3F));
        return 3;
    }

    out[0] = (uint8_t)(0xF0 | (codepoint >> 18));
    out[1] = (uint8_t)(0x80 | ((codepoint >> 12) & 0x3F));
    out[2] = (uint8_t)(0x80 | ((codepoint >> 6) & 0x3F));
    out[3] = (uint8_t)(0x80 | (codepoint & 0x3F));
    return 4;
}

bool unicode_is_valid_codepoint(unicode_codepoint_t codepoint) {
    if (codepoint > 0x10FFFF) {
        return false;
    }
    if (codepoint >= 0xD800 && codepoint <= 0xDFFF) {
        return false;
    }
    return true;
}

bool unicode_is_control_codepoint(unicode_codepoint_t codepoint) {
    return (codepoint < 0x20) || (codepoint >= 0x7F && codepoint < 0xA0);
}

bool unicode_is_combining_codepoint(unicode_codepoint_t codepoint) {
    return is_in_intervals(codepoint, kCombiningTable,
                           sizeof(kCombiningTable) / sizeof(unicode_interval_t));
}

static bool unicode_is_zero_width_format(unicode_codepoint_t codepoint) {
    return is_in_intervals(codepoint, kZeroWidthTable,
                           sizeof(kZeroWidthTable) / sizeof(unicode_interval_t));
}

int unicode_codepoint_width(unicode_codepoint_t codepoint) {
    if (codepoint >= 0x20 && codepoint < 0x7F) {
        return 1;
    }
    if (!unicode_is_valid_codepoint(codepoint)) {
        return 0;
    }
    if (unicode_is_control_codepoint(codepoint)) {
        return 0;
    }
    if (unicode_is_combining_codepoint(codepoint)) {
        return 0;
    }
    if (unicode_is_zero_width_format(codepoint)) {
        return 0;
    }

    if (is_in_intervals(codepoint, kWideTable, sizeof(kWideTable) / sizeof(unicode_interval_t))) {
        return 2;
    }

    return 1;
}

size_t unicode_calculate_display_width(const char* str, size_t str_len, size_t* count_ansi_chars,
                                       size_t* count_visible_chars) {
    size_t display_width = 0;
    size_t ansi_chars = 0;
    size_t visible_chars = 0;

    const uint8_t* data = (const uint8_t*)str;
    ssize_t len = (ssize_t)str_len;
    ssize_t pos = 0;

    while (pos < len) {
        if (data[pos] == '\033' && pos + 1 < len) {
            pos++;
            ansi_chars++;

            if (data[pos] == '[') {
                pos++;
                ansi_chars++;

                while (pos < len && ((data[pos] >= '0' && data[pos] <= '9') || data[pos] == ';' ||
                                     data[pos] == ':' || data[pos] == '<' || data[pos] == '=' ||
                                     data[pos] == '>' || data[pos] == '?')) {
                    pos++;
                    ansi_chars++;
                }

                if (pos < len) {
                    pos++;
                    ansi_chars++;
                }
            } else if (data[pos] == ']') {
                pos++;
                ansi_chars++;

                while (pos < len) {
                    if (data[pos] == '\007') {
                        pos++;
                        ansi_chars++;
                        break;
                    }
                    if (data[pos] == '\033' && pos + 1 < len && data[pos + 1] == '\\') {
                        pos += 2;
                        ansi_chars += 2;
                        break;
                    }
                    pos++;
                    ansi_chars++;
                }
            } else {
                pos++;
                ansi_chars++;
            }
            continue;
        }

        unicode_codepoint_t codepoint = 0;
        ssize_t bytes_read = 0;
        bool ok = unicode_decode_utf8(data + pos, len - pos, &codepoint, &bytes_read);
        if (!ok || bytes_read <= 0) {
            ++display_width;
            ++visible_chars;
            pos += (bytes_read > 0) ? bytes_read : 1;
            continue;
        }

        int char_width = unicode_codepoint_width(codepoint);
        if (char_width > 0) {
            display_width += (size_t)char_width;
            ++visible_chars;
        }

        pos += bytes_read;
    }

    if (count_ansi_chars != NULL) {
        *count_ansi_chars = ansi_chars;
    }
    if (count_visible_chars != NULL) {
        *count_visible_chars = visible_chars;
    }

    return display_width;
}

size_t unicode_calculate_utf8_width(const char* str, size_t str_len) {
    size_t width = 0;

    const uint8_t* data = (const uint8_t*)str;
    ssize_t len = (ssize_t)str_len;
    ssize_t pos = 0;

    while (pos < len) {
        unicode_codepoint_t codepoint = 0;
        ssize_t bytes_read = 0;
        bool ok = unicode_decode_utf8(data + pos, len - pos, &codepoint, &bytes_read);
        if (!ok || bytes_read <= 0) {
            ++width;
            pos += (bytes_read > 0) ? bytes_read : 1;
            continue;
        }

        int char_width = unicode_codepoint_width(codepoint);
        width += (char_width > 0) ? (size_t)char_width : 0;

        pos += bytes_read;
    }

    return width;
}
